import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"内蔵メモリ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/providers/memory/builtin.md","filePath":"ja/integrations/providers/memory/builtin.md","lastUpdated":1792323081000}'),o={name:"ja/integrations/providers/memory/builtin.md"};function r(n,t,l,d,h,p){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="内蔵メモリ" tabindex="-1">内蔵メモリ <a class="header-anchor" href="#内蔵メモリ" aria-label="Permalink to &quot;内蔵メモリ&quot;">​</a></h1><p>Memoh に標準搭載されているデフォルトのメモリバックエンドで、Memoh の抽出／検索フローに接続します。次をサポートします。</p><ul><li>会話からのメモリ抽出</li><li>チャット時のセマンティック検索</li><li>手動での作成・編集</li><li>メモリ圧縮とストア全体の再構築</li></ul><hr><h2 id="動作のしくみ" tabindex="-1">動作のしくみ <a class="header-anchor" href="#動作のしくみ" aria-label="Permalink to &quot;動作のしくみ&quot;">​</a></h2><p>内蔵プロバイダーは <strong>graph</strong> モードで動作します。メモリのノードとエッジは唯一の正となるデータとして PostgreSQL に保存され、そこから Markdown ビュー（Bot ワークスペース内の <code>memory/</code> bundle と <code>MEMORY.md</code>）が派生して、Agent が読み書きできます。</p><p>セマンティック検索は、その上に重ねる任意のレイヤーです。</p><table tabindex="0"><thead><tr><th>レイヤー</th><th>ストレージ</th><th>必要なもの</th><th>提供されるもの</th></tr></thead><tbody><tr><td><strong>Graph</strong>（常時有効）</td><td>PostgreSQL のメモリノード／エッジ</td><td>メインデータベースのみ</td><td>構造化されたリコール、メモリ間の関係、圧縮、再構築</td></tr><tr><td><strong>セマンティックインデックス</strong>（任意）</td><td><code>pgvector</code> データベース</td><td>Compose スタックの <code>[pgvector]</code> データベース<strong>に加えて</strong>、プロバイダーで embedding モデルを選択していること</td><td>メモリノードに対するベクトル類似度検索</td></tr></tbody></table><p>embedding モデルを選んでいない場合や <code>pgvector</code> を設定していない場合でも、プロバイダーは graph のみのモードでそのまま動作し、セマンティック検索だけがスキップされます。</p><hr><h2 id="作成する" tabindex="-1">作成する <a class="header-anchor" href="#作成する" aria-label="Permalink to &quot;作成する&quot;">​</a></h2><ol><li><strong>Memory Providers</strong> を開きます。</li><li><strong>Add Memory Provider</strong> をクリックします。</li><li><strong>Name</strong> を入力し、<strong>Provider Type</strong> で <code>builtin</code> を選びます。</li><li><strong>Create</strong> をクリックします。</li></ol><hr><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>Embedding Model</strong></td><td>任意。いずれかのモデルプロバイダーの embedding モデルです。選択すると（かつ <code>pgvector</code> が利用可能なら）メモリノードがベクトル化され、セマンティック検索が有効になります。空のままにすると graph のみのモードです。</td></tr></tbody></table><p><strong>Edit</strong> と <strong>Delete</strong> は通常どおり使えます。</p><hr><h2 id="依存関係" tabindex="-1">依存関係 <a class="header-anchor" href="#依存関係" aria-label="Permalink to &quot;依存関係&quot;">​</a></h2><h3 id="graph-のみ" tabindex="-1">graph のみ <a class="header-anchor" href="#graph-のみ" aria-label="Permalink to &quot;graph のみ&quot;">​</a></h3><p>メインの PostgreSQL 以外に追加の依存はありません。</p><h3 id="セマンティックインデックス" tabindex="-1">セマンティックインデックス <a class="header-anchor" href="#セマンティックインデックス" aria-label="Permalink to &quot;セマンティックインデックス&quot;">​</a></h3><p>デフォルトの Docker Compose スタックには <code>pgvector</code> サービスが含まれており、<code>config.toml</code> にも対応するセクションがあります。</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgvector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pgvector&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">password = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh123&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">database = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh_vector&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sslmode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;disable&quot;</span></span></code></pre></div><p>その上で、プロバイダーで <strong>Embedding Model</strong> を 1 つ選びます。ベクトルは選択したモデルプロバイダー（OpenAI、Gemini、Ollama など）で生成されるため、そのプロバイダーで embedding モデルが利用できる必要があります。</p><hr><h2 id="bot-に割り当てる" tabindex="-1">Bot に割り当てる <a class="header-anchor" href="#bot-に割り当てる" aria-label="Permalink to &quot;Bot に割り当てる&quot;">​</a></h2><ol><li><strong>Bots</strong> → Bot</li><li><strong>一般</strong> → <strong>Memory Provider</strong></li><li>保存</li></ol><p>選択していない場合、実行時にこのプロバイダーは使われません。</p><hr><h2 id="設定後" tabindex="-1">設定後 <a class="header-anchor" href="#設定後" aria-label="Permalink to &quot;設定後&quot;">​</a></h2><p>個々のメモリは、Bot の <strong>メモリ</strong> タブで管理します。</p><ul><li>手動で新規作成</li><li>会話から抽出</li><li>検索・編集・削除</li><li>メモリストアの圧縮・再構築</li></ul><p>日常の操作は <a href="./../../../guides/memory.html">長期メモリ</a> を参照してください。</p>`,33)])])}const k=a(o,[["render",r]]);export{c as __pageData,k as default};
